-- Runtime support for Lua code generated by golua (the tsc-lua Go to LuaJIT transpiler).
-- Value representation:
--   bool/string              plain Lua values
--   int/uint/uintptr         Lua numbers holding the exact value (no wraparound at 2^64)
--   int32/uint32             Lua numbers holding the signed 32-bit pattern (as bit.* returns it)
--   int8/int16/uint8/uint16  Lua numbers holding the value
--   int64/uint64             int64_t/uint64_t FFI integers (named ID types: plain numbers)
--   float64/float32          Lua numbers (float32 rounded to single precision)
--   struct                   table with flattened fields, metatable T.pmt (or T.vmt when boxed as a value)
--   *struct                  the same table as the struct value it points to
--   *T (non-struct)          box table {v = value} (or a proxy with the same shape)
--   array                    1-based Lua table
--   slice                    {backing table, 1-based offset, len, cap} by position; nil slice is nil
--   map                      Lua table with the entry count at key LEN
--   interface                raw value for bool/string/int/*struct/struct values,
--                            otherwise a wrapper {__t = type, __v = value} (float64 included)

local rt = {}

local ffi = require('ffi')
local bit = require('bit')
local setmetatable, getmetatable, rawget, rawset, type, select, error, pcall, tostring, tonumber, next =
	setmetatable, getmetatable, rawget, rawset, type, select, error, pcall, tostring, tonumber, next
local math_floor, math_ceil = math.floor, math.ceil
local band, bor, bxor, bnot, lshift, rshift, arshift, tobit =
	bit.band, bit.bor, bit.bxor, bit.bnot, bit.lshift, bit.rshift, bit.arshift, bit.tobit
local sbyte, schar, ssub, sformat = string.byte, string.char, string.sub, string.format
local tconcat, tunpack, tmove = table.concat, table.unpack, table.move
local tcreate = require('table.new')
local coroutine = coroutine

local I64, U64 = ffi.typeof('int64_t'), ffi.typeof('uint64_t')
rt.I64, rt.U64 = I64, U64

-- TSCLUA_GC_PAUSE and TSCLUA_GC_STEPMUL tune LuaJIT's incremental collector. A step multiplier
-- of 400 (LuaJIT's default is 200) keeps the collector closer behind the compiler's allocation:
-- it cut Excalidraw's peak from 9 to 7.6 GB at the same speed.
collectgarbage('setpause', tonumber(os.getenv('TSCLUA_GC_PAUSE') or '') or 200)
collectgarbage('setstepmul', tonumber(os.getenv('TSCLUA_GC_STEPMUL') or '') or 400)

-- LuaJIT's default trace limits suit small programs, and the compiler is 19 MB of Lua: without
-- room for more traces the JIT flushes them all and starts over. Higher hot counts keep it from
-- recording code that runs only a few times. TSCLUA_JIT_OPT replaces these (space separated
-- jit.opt.start parameters) and TSCLUA_JIT=off runs the interpreter only.
if os.getenv('TSCLUA_JIT') == 'off' then
	jit.off()
else
	local opts = os.getenv('TSCLUA_JIT_OPT')
	if opts then
		local list = {}
		for o in opts:gmatch('%S+') do
			list[#list + 1] = o
		end
		jit.opt.start(tunpack(list))
	else
		jit.opt.start(
			'maxtrace=65000',
			'maxrecord=16000',
			'maxmcode=524288',
			'sizemcode=4096',
			'maxside=400',
			'maxsnap=1000',
			'hotloop=1000',
			'hotexit=200'
		)
	end
end

rt.LEN = setmetatable({}, {
	__name = 'LEN',
	__tostring = function()
		return 'LEN'
	end,
})
local LEN = rt.LEN
rt.E = setmetatable({}, {
	__newindex = function()
		error('assignment to entry in nil map', 2)
	end,
})
local E = rt.E
rt.NIL = setmetatable({}, {
	__name = 'NIL',
	__tostring = function()
		return 'NIL'
	end,
})
local NIL = rt.NIL
-- Map key standing in for a nil pointer key, since Lua tables cannot have nil keys.
rt.NILKEY = setmetatable({}, { __name = 'NILKEY' })
local NILKEY = rt.NILKEY

---------------------------------------------------------------------------
-- Packages

rt.pkgs = {}

function rt.package(path)
	local P = {}
	rt.pkgs[path] = P
	return P
end

function rt.import(mod)
	local P = require(mod)
	local init = rawget(P, '__init')
	if init then
		init()
	end
	return P
end

-- Lazily evaluated type constants: TY[i] = thunk registers, TY[i] evaluates once.
function rt.lazytypes()
	local thunks = {}
	return setmetatable({}, {
		__newindex = function(_, k, f)
			thunks[k] = f
		end,
		__index = function(t, k)
			local f = thunks[k]
			if not f then
				return nil
			end
			thunks[k] = nil
			local v = f()
			rawset(t, k, v)
			return v
		end,
	})
end

function rt.nobody(name)
	error('function has no Lua implementation: ' .. name, 2)
end

function rt.unsupported()
	error('unsupported Go construct reached at runtime', 2)
end

---------------------------------------------------------------------------
-- Panics, defer and recover

local PanicMT = { __name = 'GoPanic' }
PanicMT.__tostring = function(p)
	return 'panic: ' .. rt.panicString(p.value)
end

function rt.panic(v)
	error(setmetatable({ value = v, tb = debug.traceback('', 2) }, PanicMT), 0)
end

function rt.ispanic(e)
	return getmetatable(e) == PanicMT
end

-- tb is the xpcall handler for functions with defers: Lua errors become runtime error panics
-- that keep the traceback of where they happened.
local tracePanics = os.getenv('TSCLUA_TRACE_PANICS') ~= nil

function rt.tb(e)
	if tracePanics then
		io.stderr:write(
			'[panic trace] ',
			tostring(getmetatable(e) == PanicMT and rt.panicString(e.value) or e),
			'\n',
			debug.traceback('', 2),
			'\n'
		)
	end
	local mt = getmetatable(e)
	if mt == PanicMT or (mt and (mt.__name == 'Goexit' or mt == rt.ExitError)) then
		return e
	end
	return setmetatable({ value = rt.runtimeError(tostring(e)), tb = debug.traceback(tostring(e), 2) }, PanicMT)
end

local curpanic = nil

-- rundefers runs deferred calls after a protected function body finished.
function rt.rundefers(df, ok, err)
	local p = nil
	if not ok then
		p = { err = err }
	end
	local saved = curpanic
	for i = #df, 1, -1 do
		local d = df[i]
		df[i] = nil
		curpanic = p
		local ok2, err2 = pcall(d)
		if p and p.recovered then
			p = nil
		end
		if not ok2 then
			p = { err = err2 }
		end
	end
	curpanic = saved
	if p then
		error(p.err, 0)
	end
end

-- finish completes a call whose body ran as xpcall(body, rt.tb, df, ...): it runs the deferred
-- calls and returns the body's results, or after a recovered panic the zero values from zero
-- (nil when every result's zero value is nil).
function rt.finish(df, zero, ok, ...)
	if ok and df[1] == nil then
		return ...
	end
	rt.rundefers(df, ok, (...))
	if ok then
		return ...
	end
	if zero then
		return zero()
	end
end

-- thunk is a deferred call of f with arguments evaluated at the defer statement.
local Thunk = {
	__call = function(t)
		return t[1](tunpack(t, 2, t.n))
	end,
}
function rt.thunk(f, ...)
	local t = { f, ... }
	t.n = select('#', ...) + 1
	return setmetatable(t, Thunk)
end

-- closure makes the metatable of a converted function literal: its values are tables of the
-- variables it captures, called through __call (see funcLit in transpiler/expr.go).
function rt.closure(f)
	return { __call = f }
end

-- panicValue converts a Lua error object into the Go value passed to panic.
function rt.panicValue(err)
	if getmetatable(err) == PanicMT then
		return err.value
	end
	if rt.ExitError and getmetatable(err) == rt.ExitError then
		error(err, 0)
	end
	return rt.runtimeError(tostring(err))
end

-- goexit unwinds the current goroutine like runtime.Goexit: deferred calls run, but recover
-- does not stop it.
local GoexitMT = { __name = 'Goexit' }
function rt.goexit()
	error(setmetatable({}, GoexitMT), 0)
end

function rt.isgoexit(err)
	return getmetatable(err) == GoexitMT
end

function rt.recover()
	local p = curpanic
	if p and not p.recovered and getmetatable(p.err) ~= GoexitMT then
		p.recovered = true
		return rt.panicValue(p.err)
	end
	return nil
end

---------------------------------------------------------------------------
-- Type descriptors

local nextTypeId = 0
local function newType(kind, str)
	nextTypeId = nextTypeId + 1
	local T = { id = nextTypeId, kind = kind, str = str }
	T.wmt = { __type = T }
	return T
end
rt.newType = newType

local function identity(x)
	return x
end

local function wrapper(T, v)
	return setmetatable({ __t = T, __v = v }, T.wmt)
end

function rt.box(T, v)
	return setmetatable({ __t = T, __v = v }, T.wmt)
end

local intWrap = {
	int8 = function(x)
		return arshift(lshift(x, 24), 24)
	end,
	int16 = function(x)
		return arshift(lshift(x, 16), 16)
	end,
	int32 = tobit,
	uint32 = tobit,
	uint8 = function(x)
		return band(x, 0xFF)
	end,
	uint16 = function(x)
		return band(x, 0xFFFF)
	end,
}

local f32buf = ffi.new('float[1]')
function rt.f32(x)
	f32buf[0] = x
	return f32buf[0]
end

-- bitcast reinterprets the bits of a basic value as another basic type (unsafe pointer casts).
local castBuf = ffi.new(
	'union { double d; float f; int64_t i64; uint64_t u64; int32_t i32; uint32_t u32; int16_t i16; uint16_t u16; int8_t i8; uint8_t u8; }'
)
local castFields = {
	float64 = 'd',
	float32 = 'f',
	int64 = 'i64',
	uint64 = 'u64',
	int = 'i64',
	uint = 'u64',
	uintptr = 'u64',
	int32 = 'i32',
	uint32 = 'i32',
	int16 = 'i16',
	uint16 = 'u16',
	int8 = 'i8',
	uint8 = 'u8',
}
function rt.bitcast(from, to, v)
	castBuf.u64 = 0
	castBuf[castFields[from]] = v
	local r = castBuf[castFields[to]]
	if to == 'int' or to == 'uint' or to == 'uintptr' then
		return tonumber(r)
	end
	return r
end

local function scalarOps(T, zero)
	T.zero = function()
		return zero
	end
	T.clone = identity
	T.copy = function()
		error('copy into scalar')
	end
	T.eq = function(a, b)
		return a == b
	end
	T.mapkey = identity
	T.direct = true
	T.venc = 'plain'
	T.new = function()
		return { v = zero }
	end
end

local basicKinds = {
	'bool',
	'int',
	'int8',
	'int16',
	'int32',
	'int64',
	'uint',
	'uint8',
	'uint16',
	'uint32',
	'uint64',
	'uintptr',
	'float32',
	'float64',
	'complex64',
	'complex128',
	'string',
	'unsafeptr',
}
-- Kinds whose values are stored in interfaces as plain Lua values. Only int of the numeric
-- kinds: int and float64 values are both Lua numbers, so float64 is wrapped.
local rawKinds = { bool = true, string = true, int = true }

-- FFI integers are distinct objects per value, so tables are keyed by their value as a number
-- when that is exact, and as decimal text otherwise. Plain numbers (which natives sometimes
-- store in 64-bit fields) get the same keys.
local function int64Key(v)
	if type(v) == 'number' then
		return v
	end
	local n = tonumber(v)
	if n < 9007199254740992 and n > -9007199254740992 then
		return n
	end
	return (tostring(v):gsub('U?LL$', ''))
end
rt.int64Key = int64Key

-- The 64-bit kinds held as FFI integers.
local wideKinds = { int64 = true, uint64 = true, uint = true, uintptr = true }

for _, k in ipairs(basicKinds) do
	local T = newType(k, k == 'unsafeptr' and 'unsafe.Pointer' or k)
	T.basic = true
	local zero
	if k == 'bool' then
		zero = false
	elseif k == 'string' then
		zero = ''
	elseif k == 'float32' or k == 'float64' then
		zero = 0.0
	elseif k == 'unsafeptr' then
		zero = nil
	elseif k == 'complex64' or k == 'complex128' then
		zero = nil
	elseif k == 'int64' then
		zero = I64(0)
	elseif wideKinds[k] then
		zero = U64(0)
	else
		zero = 0
	end
	scalarOps(T, zero)
	if wideKinds[k] then
		T.mapkey = int64Key
		T.direct = false
	end
	T.wrap = intWrap[k] or (k == 'float32' and rt.f32) or identity
	if rawKinds[k] then
		T.box = identity
	else
		T.box = function(v)
			return wrapper(T, v)
		end
	end
	if k == 'unsafeptr' then
		T.venc = 'nilable'
	end
	rt[k] = T
end
rt.byte = rt.uint8
rt.rune = rt.int32
rt.invalid = newType('invalid', 'invalid')

-- The 64-bit kinds with values held as plain numbers, for named ID types (see narrow64 in
-- transpiler/numbers.go).
for _, k in ipairs({ 'int64', 'uint64' }) do
	local T = newType(k, k)
	T.basic = true
	T.narrow = true
	scalarOps(T, 0)
	T.wrap = identity
	T.box = function(v)
		return wrapper(T, v)
	end
	rt[k .. 'd'] = T
end

local function isFloatKind(k)
	return k == 'float32' or k == 'float64'
end

local function isIntKind(k)
	return k == 'int'
		or k == 'int8'
		or k == 'int16'
		or k == 'int32'
		or k == 'int64'
		or k == 'uint'
		or k == 'uint8'
		or k == 'uint16'
		or k == 'uint32'
		or k == 'uint64'
		or k == 'uintptr'
end
rt.isIntKind = isIntKind

-- numRep classifies a basic type's representation like repOf in transpiler/numbers.go.
local function numRep(T)
	local k = T.kind
	if k == 'float32' or k == 'float64' then
		return 'float'
	elseif T.narrow or k == 'int' then
		return 'int'
	elseif k == 'int32' or k == 'uint32' then
		return 'int32'
	elseif k == 'int8' or k == 'int16' or k == 'uint8' or k == 'uint16' then
		return 'small'
	elseif wideKinds[k] then
		return '64'
	end
	return nil
end
rt.numRep = numRep

local function isUnsignedKind(k)
	return k == 'uint' or k == 'uintptr' or k == 'uint8' or k == 'uint16' or k == 'uint32' or k == 'uint64'
end

-- Generic constant and arithmetic helpers used inside generic code, mirroring what the
-- transpiler emits for each representation.
local function setNumericOps(T)
	local k = T.kind
	local rep = numRep(T)
	local unsigned = isUnsignedKind(k)
	T.const = function(c)
		return rt.convnum(nil, T, c)
	end
	T.op = function(op, a, b)
		if k == 'string' then
			if op == '+' then
				return a .. b
			end
		end
		local w = T.wrap or identity
		if b == nil then
			if op == '-' then
				return w(-a)
			elseif op == '^' then
				if rep == 'int' then
					return unsigned and rt.unot(a) or -a - 1
				end
				return w(bnot(a))
			end
		end
		if op == '+' then
			return w(a + b)
		elseif op == '-' then
			return w(a - b)
		elseif op == '*' then
			if rep == 'int32' then
				return rt.imul(a, b)
			end
			return w(a * b)
		elseif op == '/' then
			if rep == 'float' then
				return w(a / b)
			elseif rep == '64' then
				return rt.div64(a, b)
			elseif rep == 'int32' and unsigned then
				return rt.udiv32(a, b)
			elseif unsigned then
				return rt.udiv(a, b)
			end
			return w(rt.idiv(a, b))
		elseif op == '%' then
			if rep == '64' then
				return rt.mod64(a, b)
			elseif rep == 'int32' and unsigned then
				return rt.umod32(a, b)
			elseif unsigned then
				return a % b
			end
			return math.fmod(a, b)
		elseif op == '&' or op == '|' or op == '^' or op == '&^' then
			if rep == 'int' then
				local f = op == '&' and rt.iand or op == '|' and rt.ior or op == '^' and rt.ixor or rt.iandnot
				return f(a, b)
			end
			if op == '&' then
				return band(a, b)
			elseif op == '|' then
				return bor(a, b)
			elseif op == '^' then
				return bxor(a, b)
			end
			return band(a, bnot(b))
		elseif op == '<<' then
			if rep == 'int' then
				return rt.shl(a, b)
			elseif rep == '64' then
				return rt.shl64(a, b)
			end
			return w(rt.shl32(a, b))
		elseif op == '>>' then
			if rep == 'int' then
				return rt.shr(a, b)
			elseif rep == '64' then
				return unsigned and rt.shr64(a, b) or rt.sar64(a, b)
			end
			return unsigned and rt.shr32(a, b) or rt.sar32(a, b)
		end
		error('unsupported generic operator ' .. op)
	end
end
for _, k in ipairs(basicKinds) do
	setNumericOps(rt[k])
end
setNumericOps(rt.int64d)
setNumericOps(rt.uint64d)

-- Interfaces --------------------------------------------------------------

local ifaceCache = {}

local function interfaceOps(T)
	T.zero = function()
		return nil
	end
	T.clone = identity
	T.box = identity
	T.eq = function(a, b)
		return rt.ieq(a, b)
	end
	T.mapkey = function(k)
		return rt.ikey(k)
	end
	T.direct = false
	T.venc = 'iface'
	T.new = function()
		return { v = nil }
	end
	T.wrap = identity
	T.const = identity
end

function rt.ifaceOf(methods)
	table.sort(methods)
	local key = tconcat(methods, ',')
	local T = ifaceCache[key]
	if T then
		return T
	end
	T = newType('interface', 'interface { ' .. key .. ' }')
	T.methods = methods
	T.impl = setmetatable({}, { __mode = 'k' })
	interfaceOps(T)
	ifaceCache[key] = T
	return T
end
rt.any = rt.ifaceOf({})
rt.any.str = 'interface {}'

-- Named types -------------------------------------------------------------

local function namedType(pkg, name, kind)
	local T = newType(kind, name)
	T.named = true
	T.pkg = pkg
	T.name = name
	if kind == 'struct' then
		T.pmt = { __type = false, __struct = T }
		T.vmt = { __type = T, __struct = T, __isval = true }
	end
	return T
end

function rt.named(pkg, name, kind)
	return namedType(pkg, name, kind)
end

-- define copies the representation of an underlying (unnamed) type into a named type.
function rt.define(T, U)
	T.kind = U.kind
	T.elem = U.elem
	T.key = U.key
	T.len = U.len
	T.dir = U.dir
	T.params = U.params
	T.results = U.results
	T.variadic = U.variadic
	T.zero = U.zero
	T.clone = U.clone
	T.aggr = U.aggr
	T.copy = U.copy
	T.eq = U.eq
	T.mapkey = U.mapkey
	T.direct = U.direct
	T.venc = U.venc
	T.new = U.new
	T.wrap = U.wrap
	T.const = U.const
	T.op = U.op
	T.underlying = U
	if U.kind == 'interface' then
		T.methods = U.methods
		T.impl = setmetatable({}, { __mode = 'k' })
		T.box = identity
	elseif U.basic and rawKinds[U.kind] then
		-- Named basic types are boxed (to keep their dynamic type).
		T.box = function(v)
			return wrapper(T, v)
		end
	elseif U.kind == 'ptr' and U.elem.kind == 'struct' then
		T.box = function(v)
			return rt.boxp(T, v)
		end
	elseif U.kind == 'array' then
		T.box = function(v)
			return wrapper(T, U.clone(v))
		end
	else
		T.box = function(v)
			return wrapper(T, v)
		end
	end
	if U.kind == 'map' then
		T.pairs = U.pairs
	end
	T.basic = U.basic
end

-- Generic named types: instantiated per distinct type argument list.
function rt.generic(pkg, name, nparams, init)
	local cache = {}
	local G = { generic = true, name = name }
	return setmetatable(G, {
		__call = function(_, ...)
			local key
			if nparams == 1 then
				key = (...)
			else
				local ids = {}
				for i = 1, nparams do
					ids[i] = select(i, ...).id
				end
				key = tconcat(ids, ',')
			end
			local T = cache[key]
			if T then
				return T
			end
			local names = {}
			for i = 1, nparams do
				names[i] = select(i, ...).str
			end
			T = namedType(pkg, name .. '[' .. tconcat(names, ',') .. ']', 'struct')
			T.targs = { ... }
			cache[key] = T
			init(T, ...)
			if T.kind ~= 'struct' then
				T.pmt = nil
				T.vmt = nil
			end
			return T
		end,
	})
end

-- Structs -----------------------------------------------------------------

-- leaves returns the flattened list of {key, type} stored in a struct table.
local function leaves(T)
	local l = T.leaves
	if l then
		return l
	end
	l = {}
	for _, f in ipairs(T.fields) do
		-- Flattened embedded (flags 2) and flattened named (inline f[6]) fields share this table.
		if f[4] == 2 or f[6] then
			for _, sub in ipairs(leaves(f[2])) do
				l[#l + 1] = sub
			end
		else
			l[#l + 1] = { f[1], f[2] }
		end
	end
	T.leaves = l
	return l
end
rt.leaves = leaves

local function findField(T, name)
	for _, f in ipairs(T.fields) do
		if f[3] == name and f[4] ~= 2 and not f[6] then
			return f[1]
		end
	end
	for _, f in ipairs(T.fields) do
		if f[4] == 2 or f[6] then
			local key = findField(f[2], name)
			if key ~= nil then
				return key
			end
		end
	end
	return nil
end

-- fieldkey returns where a struct keeps the field with a Go name, including fields of flattened
-- structs, for patches: the compiler's structs keep their fields in numbered slots.
function rt.fieldkey(T, name)
	return assert(findField(T, name), name)
end

local function zeroLiteral(FT)
	local k = FT.kind
	if k == 'bool' then
		return 'false'
	elseif k == 'string' then
		return "''"
	elseif k == 'float32' or k == 'float64' then
		return '0'
	elseif FT.narrow then
		return '0'
	elseif k == 'int64' then
		return '0LL'
	elseif wideKinds[k] then
		return '0ULL'
	elseif isIntKind(k) then
		return '0'
	elseif k == 'struct' or k == 'array' or k == 'complex64' or k == 'complex128' then
		return nil
	end
	return 'nil'
end

local function isAgg(FT)
	return FT.kind == 'struct' or FT.kind == 'array'
end

-- intKey renders an integer exactly for a map key; Lua's number to string conversion keeps
-- 14 significant digits.
local function intKey(x)
	if x < 1e14 and x > -1e14 then
		return x
	end
	return sformat('%d', x)
end

-- wideKey renders a 64-bit integer field for a struct map key.
local function wideKey(x)
	local k = int64Key(x)
	if type(k) == 'number' then
		return intKey(k)
	end
	return k
end

-- fieldAt renders the storage of a struct leaf in the table x: indexed fields have numeric keys.
local function fieldAt(x, key)
	if type(key) == 'number' then
		return x .. '[' .. key .. ']'
	end
	return x .. '.' .. key
end

-- LuaJIT functions take at most 60 upvalues; beyond this many, values come from a table.
local maxUpvalues = 48

-- The helpers of buildStructOps are module level: closures in it would stop the JIT from
-- compiling traces through the first use of each struct type.

-- SerializeKey is the map key function of structs with fields MK cannot concatenate.
local SerializeKey = {
	__call = function(m, v)
		return rt.serialize(m[1], v)
	end,
}

-- addUp adds a value for the generated code to reference, returning a placeholder for its name.
local function addUp(ups, v)
	ups[#ups + 1] = v
	return '\1' .. #ups .. '\2'
end

-- structItem renders one constructor entry; calls are parenthesized to keep them to one value.
local function structItem(key, code)
	if type(key) ~= 'number' then
		return key .. ' = ' .. code
	elseif code:sub(-1) == ')' then
		return '(' .. code .. ')'
	end
	return code
end

-- structEntries lists slots 1..slots positionally (nil where other structs' slots are), then
-- named fields.
local function structEntries(positional, named, slots)
	local all = {}
	for i = 1, slots do
		all[i] = positional[i] or 'nil'
	end
	for _, e in ipairs(named) do
		all[#all + 1] = e
	end
	return tconcat(all, ', ')
end

-- Build specialized zero/clone/copy/eq functions with load() for speed.
local function buildStructOps(T)
	-- The lazy functions below can outlive the build: map infos, zerofn and named types defined
	-- from an unnamed struct keep the originals, and must not rebuild (load) on every call.
	if T.built then
		return
	end
	local ls = leaves(T)
	local ups = {}
	local mt = addUp(ups, T.pmt)
	-- Constructor entries: slots (numeric keys) go positionally in slot order so they land in
	-- the table's array part, with nil in other structs' slots, then named fields.
	local zslots, cslots, znamed, cnamed, cpparts, eqparts = {}, {}, {}, {}, {}, {}
	local slots = 0
	for _, leaf in ipairs(ls) do
		local key, FT = leaf[1], leaf[2]
		local zparts, cparts = znamed, cnamed
		if type(key) == 'number' then
			zparts, cparts = zslots, cslots
			slots = math.max(slots, key)
		end
		local x, d, s, a, b = fieldAt('x', key), fieldAt('d', key), fieldAt('s', key), fieldAt('a', key), fieldAt('b', key)
		local z = zeroLiteral(FT)
		local zi, ci = #zparts + 1, #cparts + 1
		if type(key) == 'number' then
			zi, ci = key, key
		end
		if z then
			zparts[zi] = structItem(key, z)
		else
			zparts[zi] = structItem(key, addUp(ups, FT) .. '.zero()')
		end
		if isAgg(FT) then
			local u = addUp(ups, FT)
			cparts[ci] = structItem(key, u .. '.clone(' .. x .. ')')
			cpparts[#cpparts + 1] = u .. '.copy(' .. d .. ', ' .. s .. ')'
			eqparts[#eqparts + 1] = u .. '.eq(' .. a .. ', ' .. b .. ')'
		elseif FT.kind == 'slice' then
			-- Copies get their own slice header, which may later be updated in place.
			cparts[ci] = structItem(key, 'dup(' .. x .. ')')
			cpparts[#cpparts + 1] = d .. ' = dup(' .. s .. ')'
			eqparts[#eqparts + 1] = a .. ' == ' .. b
		else
			cparts[ci] = structItem(key, x)
			cpparts[#cpparts + 1] = d .. ' = ' .. s
			if FT.kind == 'interface' then
				eqparts[#eqparts + 1] = 'ieq(' .. a .. ', ' .. b .. ')'
			elseif FT.kind == 'complex64' or FT.kind == 'complex128' then
				eqparts[#eqparts + 1] = 'ceq(' .. a .. ', ' .. b .. ')'
			else
				eqparts[#eqparts + 1] = a .. ' == ' .. b
			end
		end
	end
	-- Structs of only integers and strings get a fast map key built by concatenation.
	local keyParts = {}
	for _, leaf in ipairs(ls) do
		local FT, f = leaf[2], fieldAt('v', leaf[1])
		local k = FT.kind
		if wideKinds[k] and not FT.narrow then
			keyParts[#keyParts + 1] = 'wideKey(' .. f .. ") .. '|'"
		elseif isIntKind(k) then
			keyParts[#keyParts + 1] = 'intKey(' .. f .. ") .. '|'"
		elseif k == 'string' then
			keyParts[#keyParts + 1] = '#' .. f .. " .. ':' .. " .. f
		else
			keyParts = nil
			break
		end
	end
	local mkSrc = 'local MK = nil'
	if keyParts and #keyParts > 0 then
		mkSrc = 'local MK = function(v) return ' .. tconcat(keyParts, ' .. ') .. ' end'
	end
	local src = tconcat({
		'local setmetatable, ieq, ceq, dup, intKey, wideKey, U = ...',
		'\3',
		mkSrc,
		'local Z = function() return setmetatable({' .. structEntries(zslots, znamed, slots) .. '}, ' .. mt .. ') end',
		'local C = function(x, mt) return setmetatable({' .. structEntries(cslots, cnamed, slots) .. '}, mt or ' .. mt .. ') end',
		'local CP = function(d, s) ' .. tconcat(cpparts, '; ') .. ' return d end',
		'local EQ = function(a, b) return ' .. (#eqparts > 0 and tconcat(eqparts, ' and ') or 'true') .. ' end',
		'return Z, C, CP, EQ, MK',
	}, '\n')
	if #ups <= maxUpvalues then
		local names = {}
		for i = 1, #ups do
			names[i] = 'U' .. i
		end
		local decl = #ups > 0 and ('local ' .. tconcat(names, ', ') .. ' = unpack(U, 1, ' .. #ups .. ')') or ''
		src = src:gsub('\3', decl, 1):gsub('\1(%d+)\2', 'U%1')
	else
		src = src:gsub('\3', '', 1):gsub('\1(%d+)\2', 'U[%1]')
	end
	local chunk = assert(load(src, '=struct ' .. T.str))
	local Z, C, CP, EQ, MK = chunk(setmetatable, rt.ieq, rt.ceq, rt.dupslice, intKey, wideKey, ups)
	T.zero, T.clone, T.copy, T.eq = Z, C, CP, EQ
	if MK then
		T.mapkey = MK
	else
		T.mapkey = setmetatable({ T }, SerializeKey)
	end
	T.built = true
end

local function structOps(T)
	-- Generated code checks aggr before cloning a type parameter's value.
	T.aggr = true
	-- Ops are built on first use since field types may not be defined yet.
	T.zero = function()
		buildStructOps(T)
		return T.zero()
	end
	T.clone = function(x, mt)
		buildStructOps(T)
		return T.clone(x, mt)
	end
	T.copy = function(d, s)
		buildStructOps(T)
		return T.copy(d, s)
	end
	T.eq = function(a, b)
		buildStructOps(T)
		return T.eq(a, b)
	end
	T.mapkey = function(v)
		buildStructOps(T)
		return T.mapkey(v)
	end
	T.direct = false
	T.venc = 'plain'
	T.new = function()
		return T.zero()
	end
	T.box = function(v)
		return rt.boxv(T, v)
	end
	T.wrap = identity
end

function rt.defineStruct(T, fields)
	T.kind = 'struct'
	T.fields = fields
	if not T.pmt then
		T.pmt = { __type = false, __struct = T }
		T.vmt = { __type = T, __struct = T, __isval = true }
	end
	T.pmt.__type = rt.ptrTo(T)
	structOps(T)
end

local structCache = {}
function rt.structOf(fields)
	local parts = {}
	for i, f in ipairs(fields) do
		parts[i] = f[1] .. ':' .. f[3] .. ':' .. f[2].id .. ':' .. f[4] .. ':' .. (f[5] or '') .. ':' .. tostring(f[6])
	end
	local key = tconcat(parts, ';')
	local T = structCache[key]
	if T then
		return T
	end
	local strs = {}
	for i, f in ipairs(fields) do
		strs[i] = (f[4] ~= 0 and '' or (f[3] .. ' ')) .. f[2].str
	end
	T = newType('struct', 'struct { ' .. tconcat(strs, '; ') .. ' }')
	structCache[key] = T
	rt.defineStruct(T, fields)
	return T
end

-- boxv converts a struct value to an interface value (a copy marked as a value).
function rt.boxv(T, v)
	return T.clone(v, T.vmt)
end

-- boxp converts a pointer to struct to an interface value.
function rt.boxp(PT, p)
	local pmt = PT.elem.pmt
	if p ~= nil and pmt ~= nil and getmetatable(p) == pmt then
		return p
	end
	return wrapper(PT, p)
end

function rt.setfields(t, fields)
	for k, v in next, fields do
		t[k] = v
	end
	return t
end

function rt.embedcopy(t, T, v)
	T.copy(t, v)
	return t
end

-- dupslice copies a slice header (not its elements), for struct copies. Natives may keep other
-- state in a slice-typed field (the strings.Builder patch does); that has no cap and is shared.
function rt.dupslice(s)
	if s == nil or s[4] == nil then
		return s
	end
	return { s[1], s[2], s[3], s[4] }
end

function rt.restruct(T, x)
	return T.clone(x)
end

-- Composite types ---------------------------------------------------------

-- Generic code looks up composite types on every call. The lookups are kept apart from the
-- constructors, whose closures would make every return close upvalues, which LuaJIT's JIT
-- cannot compile.
local function newPtrType(E)
	local T = newType('ptr', '*' .. E.str)
	T.elem = E
	scalarOps(T, nil)
	T.venc = 'nilable'
	if E.kind == 'struct' then
		T.box = function(v)
			return rt.boxp(T, v)
		end
		T.new = function()
			return { v = nil }
		end
	else
		T.box = function(v)
			return wrapper(T, v)
		end
	end
	E.ptr = T
	return T
end

function rt.ptrTo(E)
	return E.ptr or newPtrType(E)
end

local growCap = function(old, need)
	local nc = old * 2
	if old >= 256 then
		nc = old + math_floor((old + 768) / 4)
	end
	if nc < need then
		nc = need
	end
	return nc
end

local function newSliceType(E)
	local T = newType('slice', '[]' .. E.str)
	T.elem = E
	scalarOps(T, nil)
	T.venc = 'nilable'
	T.direct = false
	T.box = function(v)
		return wrapper(T, v)
	end
	E.slice = T
	return T
end

function rt.sliceOf(E)
	return E.slice or newSliceType(E)
end

local arrayCache = {}
function rt.arrayOf(E, n)
	local key = E.id .. ':' .. n
	local T = arrayCache[key]
	if T then
		return T
	end
	T = newType('array', '[' .. n .. ']' .. E.str)
	T.elem = E
	T.len = n
	T.aggr = true
	local agg = isAgg(E)
	-- Scalar arrays are filled from a prebuilt zero array with table.move, which runs in C.
	local template
	T.zero = function()
		local a = tcreate(n, 0)
		if agg then
			for i = 1, n do
				a[i] = E.zero()
			end
			return a
		end
		if template == nil then
			template = {}
			local z = E.zero()
			if z ~= nil then
				for i = 1, n do
					template[i] = z
				end
			end
		end
		return tmove(template, 1, n, 1, a)
	end
	T.clone = function(x)
		local a = tcreate(n, 0)
		if agg then
			for i = 1, n do
				a[i] = E.clone(x[i])
			end
		else
			tmove(x, 1, n, 1, a)
		end
		return a
	end
	T.copy = function(d, s)
		if agg then
			for i = 1, n do
				E.copy(d[i], s[i])
			end
		else
			tmove(s, 1, n, 1, d)
		end
		return d
	end
	T.eq = function(a, b)
		local eq = E.eq
		for i = 1, n do
			if not eq(a[i], b[i]) then
				return false
			end
		end
		return true
	end
	T.mapkey = function(v)
		return rt.serialize(T, v)
	end
	T.direct = false
	T.venc = 'plain'
	T.new = T.zero
	T.box = function(v)
		return wrapper(T, T.clone(v))
	end
	T.wrap = identity
	arrayCache[key] = T
	return T
end

local mapCache = {}
local function newMapType(K, V)
	local key = K.id .. ':' .. V.id
	local T = mapCache[key]
	if not T then
		T = newType('map', 'map[' .. K.str .. ']' .. V.str)
		T.key = K
		T.elem = V
		scalarOps(T, nil)
		T.venc = 'nilable'
		T.direct = false
		T.box = function(v)
			return wrapper(T, v)
		end
		mapCache[key] = T
	end
	local byElem = K.maps
	if not byElem then
		byElem = {}
		K.maps = byElem
	end
	byElem[V] = T
	return T
end

function rt.mapOf(K, V)
	-- Generic code builds map types on every call, so look them up without building a string key.
	local byElem = K.maps
	return byElem and byElem[V] or newMapType(K, V)
end

local chanCache = {}
function rt.chanOf(E, dir)
	local key = E.id .. ':' .. dir
	local T = chanCache[key]
	if T then
		return T
	end
	local prefix = dir == 1 and 'chan<- ' or dir == 2 and '<-chan ' or 'chan '
	T = newType('chan', prefix .. E.str)
	T.elem = E
	T.dir = dir
	scalarOps(T, nil)
	T.venc = 'nilable'
	T.box = function(v)
		return wrapper(T, v)
	end
	chanCache[key] = T
	return T
end

local funcCache = {}
function rt.funcOf(params, results, variadic)
	local ps, rs = {}, {}
	for i, p in ipairs(params) do
		ps[i] = p.str
	end
	for i, r in ipairs(results) do
		rs[i] = r.str
	end
	if variadic and #ps > 0 then
		ps[#ps] = '...' .. ssub(ps[#ps], 3)
	end
	local str = 'func(' .. tconcat(ps, ', ') .. ')'
	if #rs == 1 then
		str = str .. ' ' .. rs[1]
	elseif #rs > 1 then
		str = str .. ' (' .. tconcat(rs, ', ') .. ')'
	end
	local T = funcCache[str]
	if T then
		return T
	end
	T = newType('func', str)
	T.params = params
	T.results = results
	T.variadic = variadic
	scalarOps(T, nil)
	T.venc = 'nilable'
	T.direct = false
	T.box = function(v)
		return wrapper(T, v)
	end
	funcCache[str] = T
	return T
end

rt.error = rt.ifaceOf({ 'Error' })
rt.error = (function()
	local T = namedType('', 'error', 'interface')
	rt.define(T, rt.ifaceOf({ 'Error' }))
	return T
end)()

function rt.zerofn(T)
	return T.zero
end

local kindSizes = {
	bool = 1,
	int8 = 1,
	uint8 = 1,
	int16 = 2,
	uint16 = 2,
	int32 = 4,
	uint32 = 4,
	float32 = 4,
	int = 8,
	int64 = 8,
	uint = 8,
	uint64 = 8,
	uintptr = 8,
	float64 = 8,
	complex64 = 8,
	complex128 = 16,
	string = 16,
	slice = 24,
	interface = 16,
	ptr = 8,
	map = 8,
	chan = 8,
	func = 8,
	unsafeptr = 8,
}

-- sizeof approximates unsafe.Sizeof for types only known at runtime (generic code).
function rt.sizeof(T)
	local size = T.size
	if size then
		return size
	end
	size = rt.computeSize(T)
	T.size = size
	return size
end

function rt.computeSize(T)
	local k = T.kind
	if k == 'array' then
		return rt.sizeof(T.elem) * T.len
	elseif k == 'struct' then
		local n = 0
		for _, leaf in ipairs(leaves(T)) do
			n = n + rt.sizeof(leaf[2])
		end
		return n
	end
	return kindSizes[k] or 8
end

---------------------------------------------------------------------------
-- Methods and interfaces

-- unwrapSet makes the method table of wrapped (non-struct) values: each method unwraps its
-- receiver. The wrappers are made on first use, since most methods are never called that way,
-- and are callable tables, since creating a closure stops LuaJIT's JIT from compiling a trace.
local UnwrapCall = {
	__call = function(m, w, ...)
		return m[1](w.__v, ...)
	end,
}
local unwrapMT = {
	__index = function(res, k)
		local f = rawget(res, '__set')[k]
		if f == nil then
			return nil
		end
		local m = setmetatable({ f }, UnwrapCall)
		res[k] = m
		return m
	end,
}
local function unwrapSet(set)
	return setmetatable({ __set = set }, unwrapMT)
end

-- methods installs dispatch tables. Keys are method keys ("_mName").
function rt.methods(T, vset, pset)
	local PT = rt.ptrTo(T)
	T.mset = vset
	PT.mset = pset
	if T.kind == 'struct' then
		T.vmt.__index = vset
		T.pmt.__index = pset
		PT.wmt.__index = unwrapSet(pset)
	else
		T.wmt.__index = unwrapSet(vset)
		PT.wmt.__index = unwrapSet(pset)
	end
end

function rt.implements(T, I)
	if T == nil then
		return false
	end
	local impl = I.impl
	local r = impl[T]
	if r ~= nil then
		return r
	end
	r = true
	local mset = T.mset
	if T.kind == 'interface' then
		mset = {}
		for _, m in ipairs(T.methods) do
			mset['_m' .. m] = true
		end
	end
	for _, m in ipairs(I.methods) do
		if not mset or not mset['_m' .. m] then
			r = false
			break
		end
	end
	impl[T] = r
	return r
end

function rt.typeof(x)
	local t = type(x)
	if t == 'table' then
		local w = rawget(x, '__t')
		if w then
			return w
		end
		local mt = getmetatable(x)
		if mt then
			return mt.__type
		end
		return nil
	elseif t == 'string' then
		return rt.string
	elseif t == 'number' then
		return rt.int
	elseif t == 'boolean' then
		return rt.bool
	end
	return nil
end
local typeof = rt.typeof

function rt.unbox(x)
	if type(x) == 'table' and rawget(x, '__t') then
		return x.__v
	end
	return x
end
local unbox = rt.unbox

local function typeName(T)
	if T == nil then
		return 'nil'
	end
	return T.str
end
rt.typeName = typeName

function rt.assert(x, T)
	local dt = typeof(x)
	if dt ~= T then
		rt.panic(rt.typeAssertionError(dt, T, nil))
	end
	return unbox(x)
end

function rt.assert2(x, T, zero)
	if typeof(x) == T then
		return unbox(x), true
	end
	return zero, false
end

function rt.asserti(x, I)
	if x == nil or not rt.implements(typeof(x), I) then
		rt.panic(rt.typeAssertionError(typeof(x), I, nil))
	end
	return x
end

function rt.asserti2(x, I)
	if x ~= nil and rt.implements(typeof(x), I) then
		return x, true
	end
	return nil, false
end

-- ieq compares two interface values.
function rt.ieq(a, b)
	if a == b then
		return true
	end
	if type(a) ~= 'table' or type(b) ~= 'table' then
		return false
	end
	local wa = rawget(a, '__t')
	if wa then
		if wa ~= rawget(b, '__t') then
			return false
		end
		local k = wa.kind
		if k == 'slice' or k == 'map' or k == 'func' then
			rt.panic(rt.runtimeError('comparing uncomparable type ' .. wa.str))
		end
		return wa.eq(a.__v, b.__v)
	end
	local ma, mb = getmetatable(a), getmetatable(b)
	if ma ~= mb or ma == nil or not ma.__isval then
		return false
	end
	return ma.__struct.eq(a, b)
end

function rt.eq(T, a, b)
	return T.eq(a, b)
end

-- Bound methods and partial application are callable tables rather than closures, since
-- LuaJIT's JIT cannot compile closure creation. Go code only ever calls func values.
local Bind1 = {
	__call = function(t, ...)
		return t[1](t[2], ...)
	end,
}
local Bind2 = {
	__call = function(t, ...)
		return t[1](t[2], t[3], ...)
	end,
}
local Bind3 = {
	__call = function(t, ...)
		return t[1](t[2], t[3], t[4], ...)
	end,
}
local Bind4 = {
	__call = function(t, ...)
		return t[1](t[2], t[3], t[4], t[5], ...)
	end,
}
local BindN = {
	__call = function(t, ...)
		local args = { tunpack(t, 2, t.n) }
		local k = t.n - 1
		local m = select('#', ...)
		for i = 1, m do
			args[k + i] = (select(i, ...))
		end
		return t[1](tunpack(args, 1, k + m))
	end,
}

function rt.bind(f, a, b, c, d, ...)
	local n = select('#', ...)
	if n > 0 then
		local t = { f, a, b, c, d, ... }
		t.n = 5 + n
		return setmetatable(t, BindN)
	end
	if d ~= nil then
		return setmetatable({ f, a, b, c, d }, Bind4)
	elseif c ~= nil then
		return setmetatable({ f, a, b, c }, Bind3)
	elseif b ~= nil then
		return setmetatable({ f, a, b }, Bind2)
	end
	return setmetatable({ f, a }, Bind1)
end
rt.partial = rt.bind

local IBind = {
	__call = function(t, ...)
		local x = t[1]
		return x[t[2]](x, ...)
	end,
}

function rt.ibind(x, key)
	if x == nil then
		rt.panic(rt.runtimeError('invalid memory address or nil pointer dereference'))
	end
	return setmetatable({ x, key }, IBind)
end

function rt.imethod(key)
	return function(r, ...)
		return r[key](r, ...)
	end
end

function rt.call(f, ...)
	return f(...)
end

---------------------------------------------------------------------------
-- Integers and floats

local function divPanic()
	rt.panic(rt.runtimeError('integer divide by zero'))
end

-- idiv is Go's truncating division of int values held as doubles (exact below 2^53).
function rt.idiv(a, b)
	if b == 0 then
		divPanic()
	end
	local q = a / b
	if q >= 0 then
		return math_floor(q)
	end
	return math_ceil(q)
end

function rt.udiv(a, b)
	if b == 0 then
		divPanic()
	end
	return math_floor(a / b)
end

-- imul multiplies 32-bit patterns modulo 2^32 without losing low bits to double rounding.
function rt.imul(a, b)
	-- Both partial products stay below 2^47, so they are exact.
	return tobit(lshift(tobit(arshift(a, 16) * b), 16) + band(a, 0xFFFF) * b)
end

local TWO32 = 4294967296

function rt.udiv32(a, b)
	if b == 0 then
		divPanic()
	end
	return tobit(math_floor((a % TWO32) / (b % TWO32)))
end

function rt.umod32(a, b)
	if b == 0 then
		divPanic()
	end
	return tobit((a % TWO32) % (b % TWO32))
end

function rt.div64(a, b)
	if b == 0 then
		divPanic()
	end
	return a / b
end

function rt.mod64(a, b)
	if b == 0 then
		divPanic()
	end
	return a % b
end

-- Shifts of int/uint values held as doubles; Go's shift counts of 64 or more shift everything out.
function rt.shl(x, n)
	if n >= 64 then
		return 0
	end
	return x * 2 ^ n
end

function rt.shr(x, n)
	if n >= 64 then
		return x < 0 and -1 or 0
	end
	return math_floor(x / 2 ^ n)
end

-- bit.* masks the count to 5 (or 6) bits, so counts beyond the width are handled here.
function rt.shl32(x, n)
	if n >= 32 then
		return 0
	end
	return lshift(x, n)
end

function rt.shr32(x, n)
	if n >= 32 then
		return 0
	end
	return rshift(x, n)
end

function rt.sar32(x, n)
	if n >= 32 then
		n = 31
	end
	return arshift(x, n)
end

function rt.shl64(x, n)
	if n >= 64 then
		return x - x
	end
	return lshift(x, n)
end

function rt.shr64(x, n)
	if n >= 64 then
		return x - x
	end
	return rshift(x, n)
end

function rt.sar64(x, n)
	if n >= 64 then
		n = 63
	end
	return arshift(x, n)
end

-- Conversions between int and uint values held as doubles move out-of-range values by 2^64.
local TWO64 = 18446744073709551616
local TWO63 = 9223372036854775808

function rt.i2u(x)
	if x < 0 then
		return x + TWO64
	end
	return x
end

function rt.u2i(x)
	if x >= TWO63 then
		return x - TWO64
	end
	return x
end

function rt.unot(x)
	return TWO64 - 1 - x
end

-- lo32 is the low 32 bits of an FFI integer as a signed 32-bit pattern.
function rt.lo32(x)
	return tobit(tonumber(band(x, 0xFFFFFFFFULL)))
end

-- Bitwise operations on int/uint values held as doubles. Values in int32 range (the usual
-- case) take one bit operation; others are split into 32-bit halves.
local function split(x)
	local hi = math_floor(x / TWO32)
	return hi, x - hi * TWO32
end

local function bitop53(f, a, b)
	local ah, al = split(a)
	local bh, bl = split(b)
	return f(ah, bh) * TWO32 + f(al, bl) % TWO32
end

local function andnot(a, b)
	return band(a, bnot(b))
end

function rt.iand(a, b)
	if a == tobit(a) and b == tobit(b) then
		return band(a, b)
	end
	return bitop53(band, a, b)
end

function rt.ior(a, b)
	if a == tobit(a) and b == tobit(b) then
		return bor(a, b)
	end
	return bitop53(bor, a, b)
end

function rt.ixor(a, b)
	if a == tobit(a) and b == tobit(b) then
		return bxor(a, b)
	end
	return bitop53(bxor, a, b)
end

function rt.iandnot(a, b)
	if a == tobit(a) and b == tobit(b) then
		return andnot(a, b)
	end
	return bitop53(andnot, a, b)
end

function rt.f2i(x)
	if x ~= x then
		return -TWO63
	end
	if x >= 0 then
		return math_floor(x)
	end
	return math_ceil(x)
end

function rt.f2u(x)
	return rt.f2i(x)
end

-- plainNumber reads an integer of type F (or an untyped constant when F is nil) as a Lua number.
local function plainNumber(F, v)
	if type(v) == 'cdata' then
		return tonumber(v)
	end
	if F and F.kind == 'uint32' then
		return v % TWO32
	end
	return v
end

-- convnum converts a number of type F to type T (F nil: a constant), like numConversion in
-- transpiler/numbers.go.
function rt.convnum(F, T, v)
	local rep = numRep(T)
	local frep = F and numRep(F)
	if rep == 'float' then
		local n = plainNumber(F, v)
		if T.kind == 'float32' then
			return rt.f32(n)
		end
		return n
	end
	if frep == 'float' then
		if rep == '64' then
			return T.kind == 'int64' and I64(v) or U64(v)
		end
		return T.wrap(rt.f2i(v))
	end
	if rep == '64' then
		local ctor = T.kind == 'int64' and I64 or U64
		if type(v) == 'cdata' then
			return ctor(v)
		end
		return ctor(plainNumber(F, v))
	end
	if type(v) == 'cdata' then
		if rep == 'int' then
			if not isUnsignedKind(T.kind) then
				return tonumber(I64(v))
			end
			return tonumber(v)
		end
		return T.wrap(rt.lo32(v))
	end
	if rep == 'int' then
		local n = plainNumber(F, v)
		if F then
			local fu, tu = isUnsignedKind(F.kind), isUnsignedKind(T.kind)
			if not fu and tu then
				return rt.i2u(n)
			elseif fu and not tu then
				return rt.u2i(n)
			end
		end
		return n
	end
	return T.wrap(v)
end

-- min and max for kinds whose order is not the Lua order of their values (uint32 patterns) or
-- that math.min cannot take (FFI integers, strings).
local function less(T, a, b)
	if T.kind == 'uint32' then
		return a % TWO32 < b % TWO32
	end
	return a < b
end

function rt.min(T, a, ...)
	local r = a
	for i = 1, select('#', ...) do
		local v = select(i, ...)
		if less(T, v, r) then
			r = v
		end
	end
	return r
end

function rt.max(T, a, ...)
	local r = a
	for i = 1, select('#', ...) do
		local v = select(i, ...)
		if less(T, r, v) then
			r = v
		end
	end
	return r
end

function rt.fmin(a, ...)
	local r = a
	for i = 1, select('#', ...) do
		local v = select(i, ...)
		if v ~= v or r ~= r then
			r = 0.0 / 0.0
		elseif v < r or (v == 0 and r == 0 and 1 / v < 0) then
			r = v
		end
	end
	return r
end

function rt.fmax(a, ...)
	local r = a
	for i = 1, select('#', ...) do
		local v = select(i, ...)
		if v ~= v or r ~= r then
			r = 0.0 / 0.0
		elseif v > r or (v == 0 and r == 0 and 1 / r < 0) then
			r = v
		end
	end
	return r
end

-- Complex numbers are {re, im} tables; they are rare in practice.
local ComplexMT = {}
function rt.complex(re, im)
	return setmetatable({ re = re + 0.0, im = im + 0.0 }, ComplexMT)
end
function rt.cadd(a, b)
	return rt.complex(a.re + b.re, a.im + b.im)
end
function rt.csub(a, b)
	return rt.complex(a.re - b.re, a.im - b.im)
end
function rt.cmul(a, b)
	return rt.complex(a.re * b.re - a.im * b.im, a.re * b.im + a.im * b.re)
end
function rt.cdiv(a, b)
	local d = b.re * b.re + b.im * b.im
	return rt.complex((a.re * b.re + a.im * b.im) / d, (a.im * b.re - a.re * b.im) / d)
end
function rt.cneg(a)
	return rt.complex(-a.re, -a.im)
end
function rt.ceq(a, b)
	return a.re == b.re and a.im == b.im
end
rt.complex128.zero = function()
	return rt.complex(0.0, 0.0)
end
rt.complex64.zero = rt.complex128.zero

-- Conversions between type parameters' dynamic types.
function rt.convert(from, to, v)
	if to.kind == 'interface' then
		if from.kind == 'interface' then
			return v
		end
		return from.box(v)
	end
	local fk, tk = from.kind, to.kind
	if tk == 'string' then
		if fk == 'string' then
			return v
		elseif isIntKind(fk) then
			return rt.runestr(v)
		elseif fk == 'slice' then
			if from.elem.kind == 'int32' then
				return rt.runesstr(v)
			end
			return rt.bytestr(v)
		end
	elseif tk == 'slice' and fk == 'string' then
		if to.elem.kind == 'int32' then
			return rt.strrunes(v)
		end
		return rt.strbytes(v)
	elseif isIntKind(fk) and tk ~= 'string' or isFloatKind(fk) then
		if numRep(to) then
			return rt.convnum(from, to, v)
		end
	elseif tk == 'struct' and from ~= to then
		return to.clone(v)
	end
	return v
end

---------------------------------------------------------------------------
-- Strings

-- decodeRune decodes the UTF-8 sequence at 1-based byte position i with Go's rules.
local function decodeRune(s, i)
	local c = sbyte(s, i)
	if c == nil then
		return 0xFFFD, 0
	end
	if c < 0x80 then
		return c, 1
	end
	if c < 0xC2 then
		return 0xFFFD, 1
	end
	local c1 = sbyte(s, i + 1)
	if c < 0xE0 then
		if c1 and c1 >= 0x80 and c1 < 0xC0 then
			return (c - 0xC0) * 64 + (c1 - 0x80), 2
		end
		return 0xFFFD, 1
	end
	if c < 0xF0 then
		local lo, hi = 0x80, 0xBF
		if c == 0xE0 then
			lo = 0xA0
		elseif c == 0xED then
			hi = 0x9F
		end
		if not c1 or c1 < lo or c1 > hi then
			return 0xFFFD, 1
		end
		local c2 = sbyte(s, i + 2)
		if not c2 or c2 < 0x80 or c2 > 0xBF then
			return 0xFFFD, 1
		end
		return (c - 0xE0) * 4096 + (c1 - 0x80) * 64 + (c2 - 0x80), 3
	end
	if c < 0xF5 then
		local lo, hi = 0x80, 0xBF
		if c == 0xF0 then
			lo = 0x90
		elseif c == 0xF4 then
			hi = 0x8F
		end
		if not c1 or c1 < lo or c1 > hi then
			return 0xFFFD, 1
		end
		local c2 = sbyte(s, i + 2)
		if not c2 or c2 < 0x80 or c2 > 0xBF then
			return 0xFFFD, 1
		end
		local c3 = sbyte(s, i + 3)
		if not c3 or c3 < 0x80 or c3 > 0xBF then
			return 0xFFFD, 1
		end
		return (c - 0xF0) * 262144 + (c1 - 0x80) * 4096 + (c2 - 0x80) * 64 + (c3 - 0x80), 4
	end
	return 0xFFFD, 1
end
rt.decodeRune = decodeRune

-- utf8DecodeLast mirrors utf8.DecodeLastRuneInString.
local function utf8DecodeLast(s)
	local n = #s
	if n == 0 then
		return 0xFFFD, 0
	end
	local c = sbyte(s, n)
	if c < 0x80 then
		return c, 1
	end
	local lim = n - 4
	if lim < 0 then
		lim = 0
	end
	local start = n - 1
	start = start - 1
	while start >= lim do
		if band(sbyte(s, start + 1), 0xC0) ~= 0x80 then
			break
		end
		start = start - 1
	end
	if start < 0 then
		start = 0
	end
	local r, size = decodeRune(s, start + 1)
	if start + size ~= n then
		return 0xFFFD, 1
	end
	return r, size
end
rt.decodeLastRune = utf8DecodeLast

-- Range helpers operate on s[i:e] (0-based, e exclusive, nil e = #s) without copying it,
-- since Go substrings are O(1) but string.sub copies.
local sfind = string.find

function rt.decodeRuneAt(s, i, e)
	local n = #s
	e = e or n
	if i >= e then
		return 0xFFFD, 0
	end
	local c = sbyte(s, i + 1)
	if c < 0x80 then
		return c, 1
	end
	if e >= n or e - i >= 4 then
		return decodeRune(s, i + 1)
	end
	return decodeRune(ssub(s, i + 1, e), 1)
end

function rt.decodeLastRuneAt(s, e, lo)
	lo = lo or 0
	if e <= lo then
		return 0xFFFD, 0
	end
	local c = sbyte(s, e)
	if c < 0x80 then
		return c, 1
	end
	local start = e - 4
	if start < lo then
		start = lo
	end
	return utf8DecodeLast(ssub(s, start + 1, e))
end

function rt.hasPrefixAt(s, i, p, e)
	local np = #p
	if (e or #s) - i < np then
		return false
	end
	return ssub(s, i + 1, i + np) == p
end

-- indexByteFrom and indexFrom search s[i:e] (e nil: to the end). With an end, the search
-- stays within it: string.find has no end bound, and searching the rest of a source file for
-- every short substring is quadratic.
function rt.indexByteFrom(s, i, c, e)
	if e then
		for j = i + 1, e do
			if sbyte(s, j) == c then
				return j - 1 - i
			end
		end
		return -1
	end
	local j = sfind(s, schar(c), i + 1, true)
	if j == nil then
		return -1
	end
	return j - 1 - i
end

function rt.indexFrom(s, i, sub, e)
	local j
	if e then
		j = sfind(ssub(s, i + 1, e), sub, 1, true)
		if j == nil then
			return -1
		end
		return j - 1
	end
	j = sfind(s, sub, i + 1, true)
	if j == nil then
		return -1
	end
	return j - 1 - i
end

-- anyClass is the Lua character class for an ASCII set, false for other sets.
local anyClasses = {}
-- classItem escapes a non-alphanumeric byte for a class; %z stands for NUL, which would end a
-- LuaJIT pattern.
local function classItem(c)
	return c == '\0' and '%z' or '%' .. c
end
local function anyClass(chars)
	local class = anyClasses[chars]
	if class == nil then
		class = false
		if chars ~= '' and not sfind(chars, '[\128-\255]') then
			class = '[' .. chars:gsub('%W', classItem) .. ']'
		end
		anyClasses[chars] = class
	end
	return class
end
rt.anyClass = anyClass

-- indexAnyFrom is strings.IndexAny on s[i:e]. ASCII bytes never occur inside a multibyte UTF-8
-- sequence, so for an ASCII set the first matching byte is the first matching rune.
function rt.indexAnyFrom(s, i, chars, e)
	local class = anyClass(chars)
	if not class then
		return rt.import('go.strings').IndexAny(ssub(s, i + 1, e), chars)
	end
	local j
	if e then
		j = sfind(ssub(s, i + 1, e), class)
		if j == nil then
			return -1
		end
		return j - 1
	end
	j = sfind(s, class, i + 1)
	if j == nil then
		return -1
	end
	return j - 1 - i
end

-- runes iterates a string like Go's range: yields (0-based byte index, rune). The position is
-- kept in a state table rather than a closure, which LuaJIT's JIT could not compile.
local function runesNext(st)
	local s, i = st[1], st[2]
	if i > st[3] then
		return nil
	end
	local c = sbyte(s, i)
	if c < 0x80 then
		st[2] = i + 1
		return i - 1, c
	end
	local r, w = decodeRune(s, i)
	st[2] = i + w
	return i - 1, r
end

function rt.runes(s)
	return runesNext, { s, 1, #s }, nil
end

-- utf8valid reports whether s is valid UTF-8 (Go's rules: no surrogates or overlong forms).
function rt.utf8valid(s)
	local i, n = 1, #s
	while i <= n do
		local c = sbyte(s, i)
		if c < 0x80 then
			i = i + 1
		else
			local r, w = decodeRune(s, i)
			if r == 0xFFFD and w == 1 then
				return false
			end
			i = i + w
		end
	end
	return true
end

-- itoa formats an integer value (a Lua number or an FFI integer) in decimal. Lua's own number
-- to string conversion keeps only 14 significant digits.
function rt.itoa(v)
	if type(v) == 'cdata' then
		return (tostring(v):gsub('U?LL$', ''))
	end
	if v > -1e15 and v < 1e15 then
		return sformat('%d', v)
	end
	return sformat('%.0f', v)
end

function rt.runestr(r)
	if type(r) == 'cdata' then
		r = tonumber(r)
	end
	if r < 0 or r > 0x10FFFF or (r >= 0xD800 and r <= 0xDFFF) then
		return '\239\191\189'
	end
	if r < 0x80 then
		return schar(r)
	elseif r < 0x800 then
		return schar(0xC0 + rshift(r, 6), 0x80 + band(r, 0x3F))
	elseif r < 0x10000 then
		return schar(0xE0 + rshift(r, 12), 0x80 + band(rshift(r, 6), 0x3F), 0x80 + band(r, 0x3F))
	end
	return schar(0xF0 + rshift(r, 18), 0x80 + band(rshift(r, 12), 0x3F), 0x80 + band(rshift(r, 6), 0x3F), 0x80 + band(r, 0x3F))
end

local CHUNK = 4096

function rt.strbytes(s)
	local n = #s
	local a = tcreate(n, 0)
	for i = 1, n, CHUNK do
		local j = i + CHUNK - 1
		if j > n then
			j = n
		end
		tmove({ sbyte(s, i, j) }, 1, j - i + 1, i, a)
	end
	return { a, 1, n, n }
end

function rt.bytestr(sl)
	if sl == nil or sl[3] == 0 then
		return ''
	end
	local a, o, n = sl[1], sl[2], sl[3]
	if n <= CHUNK then
		return schar(tunpack(a, o, o + n - 1))
	end
	local parts = {}
	for i = 0, n - 1, CHUNK do
		local j = i + CHUNK - 1
		if j > n - 1 then
			j = n - 1
		end
		parts[#parts + 1] = schar(tunpack(a, o + i, o + j))
	end
	return tconcat(parts)
end

function rt.strrunes(s)
	local a = {}
	local n = 0
	for _, r in rt.runes(s) do
		n = n + 1
		a[n] = r
	end
	return { a, 1, n, n }
end

function rt.runesstr(sl)
	if sl == nil then
		return ''
	end
	local parts = {}
	for i = 0, sl[3] - 1 do
		parts[i + 1] = rt.runestr(sl[1][sl[2] + i])
	end
	return tconcat(parts)
end

function rt.unsafestring(p, n)
	if n == 0 then
		return ''
	end
	if type(p) == 'table' then
		local bytes = rawget(p, '__bytes')
		if bytes then
			return ssub(bytes, 1, n)
		end
		-- &b[i]: a slot pointer into a byte slice's backing table.
		local tab = rawget(p, '__tab')
		if tab then
			return rt.bytestr({ tab, rawget(p, '__key'), n, n })
		end
	end
	return rt.bytestr(rt.slice(p, 0, n))
end

function rt.unsafedata(s)
	if type(s) == 'string' then
		return { __bytes = s }
	end
	return s
end

function rt.unsafeslice(p)
	return p
end

---------------------------------------------------------------------------
-- Slices

local function boundsPanic(msg)
	rt.panic(rt.runtimeError(msg))
end

function rt.mkslice(n, c, z)
	if c == nil or c < n then
		c = n
	end
	local a = tcreate(c, 0)
	if type(z) == 'function' then
		for i = 1, c do
			a[i] = z()
		end
	elseif z ~= nil then
		for i = 1, c do
			a[i] = z
		end
	end
	return { a, 1, n, c }
end

function rt.len(s)
	if s == nil then
		return 0
	end
	if type(s) == 'string' then
		return #s
	end
	return s[3]
end

function rt.cap(s)
	if s == nil then
		return 0
	end
	return s[4]
end

function rt.sget(s, i)
	return s[1][s[2] + i]
end

function rt.sparts(s)
	if s == nil then
		return E, 1, 0
	end
	return s[1], s[2], s[3]
end

function rt.slice(s, lo, hi)
	lo = lo or 0
	if s == nil then
		if lo == 0 and (hi == nil or hi == 0) then
			return nil
		end
		boundsPanic('slice bounds out of range')
	end
	if hi == nil then
		hi = s[3]
	end
	if lo < 0 or hi < lo or hi > s[4] then
		boundsPanic(sformat('slice bounds out of range [%d:%d] with capacity %d', lo, hi, s[4]))
	end
	return { s[1], s[2] + lo, hi - lo, s[4] - lo }
end

function rt.slice3(s, lo, hi, max)
	lo = lo or 0
	if s == nil then
		return nil
	end
	if lo < 0 or hi < lo or max < hi or max > s[4] then
		boundsPanic('slice bounds out of range')
	end
	return { s[1], s[2] + lo, hi - lo, max - lo }
end

function rt.arrslice(arr, n)
	return { arr, 1, n, n }
end

function rt.slice2array(s, n)
	if s == nil or s[3] < n then
		boundsPanic('cannot convert slice to array')
	end
	local a = tcreate(n, 0)
	tmove(s[1], s[2], s[2] + n - 1, 1, a)
	return a
end

-- grow moves s's elements into a new backing array with room for `need` elements. Aggregate
-- elements (E given) are cloned: after growth Go's old and new arrays are independent.
local function grow(a, o, n, c, need, E)
	local nc = growCap(c, need)
	local na = tcreate(nc, 0)
	if n > 0 then
		if E then
			local clone = E.clone
			for i = 0, n - 1 do
				na[i + 1] = clone(a[o + i])
			end
		else
			tmove(a, o, o + n - 1, 1, na)
		end
	end
	return na, nc
end

local function aggregateType(E)
	if E ~= nil and (E.kind == 'struct' or E.kind == 'array') then
		return E
	end
	return nil
end

function rt.append1(s, v, E)
	if s == nil then
		return { { v }, 1, 1, 1 }
	end
	local n, c = s[3], s[4]
	if n < c then
		local a = s[1]
		a[s[2] + n] = v
		return { a, s[2], n + 1, c }
	end
	local na, nc = grow(s[1], s[2], n, c, n + 1, aggregateType(E))
	na[n + 1] = v
	return { na, 1, n + 1, nc }
end
local append1 = rt.append1

local function appendValues(E, s, k, ...)
	local n, c, a, o
	if s == nil then
		n, c, a, o = 0, 0, nil, 1
	else
		n, c, a, o = s[3], s[4], s[1], s[2]
	end
	if n + k > c then
		a, c = grow(a, o, n, c, n + k, E)
		o = 1
	end
	for i = 1, k do
		a[o + n + i - 1] = (select(i, ...))
	end
	return { a, o, n + k, c }
end

function rt.append(s, ...)
	local k = select('#', ...)
	if k == 1 then
		return append1(s, ...)
	end
	return appendValues(nil, s, k, ...)
end

-- appendT appends values of element type E (values are already copies).
function rt.appendT(E, s, ...)
	return appendValues(aggregateType(E), s, select('#', ...), ...)
end

function rt.appendslice(s, t, E)
	if t == nil or t[3] == 0 then
		-- A new header even when nothing is added: the result may later be updated in place.
		return rt.dupslice(s)
	end
	E = aggregateType(E)
	local k = t[3]
	local n, c, a, o
	if s == nil then
		n, c, a, o = 0, 0, nil, 1
	else
		n, c, a, o = s[3], s[4], s[1], s[2]
	end
	if n + k > c then
		a, c = grow(a, o, n, c, n + k, E)
		o = 1
	end
	if E then
		local clone = E.clone
		local ta, to = t[1], t[2]
		for i = 0, k - 1 do
			a[o + n + i] = clone(ta[to + i])
		end
	else
		tmove(t[1], t[2], t[2] + k - 1, o + n, a)
	end
	return { a, o, n + k, c }
end

function rt.appendstr(s, str)
	if #str == 0 then
		return rt.dupslice(s)
	end
	return rt.appendslice(s, rt.strbytes(str))
end

-- In-place forms of append and reslicing, used for `s = append(s, ...)` and `s = s[i:j]` when
-- nothing else can hold s's header (transpiler/inplace.go): they update the header when it has
-- room, and otherwise make a new one as usual.
local function pushValues(s, k, ...)
	local a, base = s[1], s[2] + s[3] - 1
	for i = 1, k do
		a[base + i] = (select(i, ...))
	end
	s[3] = s[3] + k
	return s
end

function rt.push1(s, v, E)
	if s ~= nil then
		local n = s[3]
		if n < s[4] then
			s[1][s[2] + n] = v
			s[3] = n + 1
			return s
		end
	end
	return append1(s, v, E)
end

function rt.pushn(s, ...)
	local k = select('#', ...)
	if s ~= nil and s[3] + k <= s[4] then
		return pushValues(s, k, ...)
	end
	return rt.append(s, ...)
end

function rt.pushT(E, s, ...)
	local k = select('#', ...)
	if s ~= nil and s[3] + k <= s[4] then
		return pushValues(s, k, ...)
	end
	return rt.appendT(E, s, ...)
end

function rt.pushslice(s, t, E)
	-- A source sharing s's array could overlap the destination; take the copying path.
	if s ~= nil and t ~= nil and t[1] ~= s[1] and s[3] + t[3] <= s[4] then
		local k = t[3]
		local a, base = s[1], s[2] + s[3]
		E = aggregateType(E)
		if E then
			local clone = E.clone
			local ta, to = t[1], t[2]
			for i = 0, k - 1 do
				a[base + i] = clone(ta[to + i])
			end
		elseif k > 0 then
			tmove(t[1], t[2], t[2] + k - 1, base, a)
		end
		s[3] = s[3] + k
		return s
	end
	return rt.appendslice(s, t, E)
end

function rt.pushstr(s, str)
	return rt.pushslice(s, #str > 0 and rt.strbytes(str) or nil)
end

function rt.reslice(s, lo, hi)
	if s == nil then
		return rt.slice(s, lo, hi)
	end
	lo = lo or 0
	if hi == nil then
		hi = s[3]
	end
	if lo < 0 or hi < lo or hi > s[4] then
		boundsPanic(sformat('slice bounds out of range [%d:%d] with capacity %d', lo, hi, s[4]))
	end
	s[2] = s[2] + lo
	s[3] = hi - lo
	s[4] = s[4] - lo
	return s
end

function rt.reslice3(s, lo, hi, max)
	if s == nil then
		return nil
	end
	lo = lo or 0
	if lo < 0 or hi < lo or max < hi or max > s[4] then
		boundsPanic('slice bounds out of range')
	end
	s[2] = s[2] + lo
	s[3] = hi - lo
	s[4] = max - lo
	return s
end

function rt.copy(dst, src, E)
	if dst == nil or src == nil then
		return 0
	end
	local n = dst[3]
	if src[3] < n then
		n = src[3]
	end
	if n == 0 then
		return 0
	end
	E = aggregateType(E)
	if not E then
		tmove(src[1], src[2], src[2] + n - 1, dst[2], dst[1])
		return n
	end
	-- Aggregates are copied by value into the destination slots, in an overlap-safe order.
	local da, doff, sa, soff = dst[1], dst[2], src[1], src[2]
	local first, last, step = 0, n - 1, 1
	if da == sa and doff > soff then
		first, last, step = n - 1, 0, -1
	end
	for i = first, last, step do
		local target = da[doff + i]
		if target == nil then
			da[doff + i] = E.clone(sa[soff + i])
		else
			E.copy(target, sa[soff + i])
		end
	end
	return n
end

function rt.copystr(dst, s)
	if dst == nil then
		return 0
	end
	local n = dst[3]
	if #s < n then
		n = #s
	end
	local a, o = dst[1], dst[2]
	for i = 1, n do
		a[o + i - 1] = sbyte(s, i)
	end
	return n
end

function rt.sclear(s, z)
	if s == nil then
		return
	end
	local a, o = s[1], s[2]
	for i = 0, s[3] - 1 do
		if type(z) == 'function' then
			a[o + i] = z()
		else
			a[o + i] = z
		end
	end
end

function rt.sparseslice(n, z, pairs)
	local s = rt.mkslice(n, n, z)
	for i = 1, #pairs, 2 do
		s[1][pairs[i] + 1] = pairs[i + 1]
	end
	return s
end

function rt.sparsearray(n, z, pairs)
	local s = rt.mkslice(n, n, z)
	local a = s[1]
	for i = 1, #pairs, 2 do
		a[pairs[i] + 1] = pairs[i + 1]
	end
	return a
end

function rt.fillarray(a, have, n, z)
	for i = have + 1, n do
		if type(z) == 'function' then
			a[i] = z()
		else
			a[i] = z
		end
	end
	return a
end

-- Pointer proxies to table slots, exposing the value as p.v like a box.
local SlotPtrMT = {
	__index = function(p, k)
		if k == 'v' then
			return p.__tab[p.__key]
		end
		return nil
	end,
	__newindex = function(p, k, v)
		if k == 'v' then
			p.__tab[p.__key] = v
		else
			rawset(p, k, v)
		end
	end,
}
-- Atomic integer struct fields hold their plain value; the transpiler compiles their common
-- methods to these (t[k] is the field). 32-bit values wrap like int32/uint32 arithmetic.
function rt.astore(t, k, v)
	t[k] = v
end

function rt.aadd(t, k, d)
	local v = t[k] + d
	t[k] = v
	return v
end

function rt.aadd32(t, k, d)
	local v = tobit(t[k] + d)
	t[k] = v
	return v
end

function rt.aswap(t, k, v)
	local old = t[k]
	t[k] = v
	return old
end

function rt.acas(t, k, old, new)
	if t[k] == old then
		t[k] = new
		return true
	end
	return false
end

-- Slot pointers are canonical per (table, key) so that &x == &x holds, as in Go.
local slotPtrs = setmetatable({}, { __mode = 'k' })
local weakValues = { __mode = 'v' }

function rt.fieldptr(t, key)
	local byKey = slotPtrs[t]
	if not byKey then
		byKey = setmetatable({}, weakValues)
		slotPtrs[t] = byKey
	end
	local p = byKey[key]
	if not p then
		p = setmetatable({ __tab = t, __key = key }, SlotPtrMT)
		byKey[key] = p
	end
	return p
end

-- elemptr is &s[i] for non-struct elements (struct elements are their own pointers).
function rt.elemptr(s, i)
	return rt.fieldptr(s[1], s[2] + i)
end

-- Pointer operations on values of a type parameter T, whose representation is only known at runtime.

function rt.elemptrT(T, s, i)
	if T.aggr then
		return s[1][s[2] + i]
	end
	return rt.fieldptr(s[1], s[2] + i)
end

function rt.fieldptrT(T, t, key)
	if T.aggr then
		return t[key]
	end
	return rt.fieldptr(t, key)
end

function rt.derefT(T, p)
	if T.aggr then
		return p
	end
	return p.v
end

-- addrT is &x for a boxed variable x of type parameter type.
function rt.addrT(T, box)
	if T.aggr then
		return box.v
	end
	return box
end

function rt.storeT(T, p, v)
	if T.aggr then
		T.copy(p, v)
	else
		p.v = v
	end
end

---------------------------------------------------------------------------
-- Maps

function rt.mkmap(hint)
	local m = tcreate(0, (hint or 0) + 1)
	m[LEN] = 0
	return m
end

function rt.mset(m, k, v)
	if m[k] == nil then
		m[LEN] = m[LEN] + 1
	end
	m[k] = v
end

function rt.mdel(m, k)
	if m ~= nil and k ~= nil and m[k] ~= nil then
		m[k] = nil
		m[LEN] = m[LEN] - 1
	end
end

function rt.mlen(m)
	if m == nil then
		return 0
	end
	return m[LEN]
end

function rt.mclear(m)
	if m == nil then
		return
	end
	for k in next, m do
		m[k] = nil
	end
	m[LEN] = 0
end

function rt.maplit(kv)
	local m = tcreate(0, math_floor(#kv / 2) + 1)
	local n = 0
	for i = 1, #kv, 2 do
		local k = kv[i]
		if m[k] == nil then
			n = n + 1
		end
		m[k] = kv[i + 1]
	end
	m[LEN] = n
	return m
end

function rt.nn(v)
	if v == NIL then
		return nil
	end
	return v
end

function rt.nilv(v)
	if v == nil then
		return NIL
	end
	return v
end

-- Map type helpers: key storage and value encoding derive from the key/elem types.
local function mapInfo(MT)
	local info = MT.minfo
	if info then
		return info
	end
	local K, V = MT.key, MT.elem
	info = { pairs = not K.direct, venc = V.venc, zero = V.zero, K = K }
	MT.minfo = info
	return info
end

local function encodeVal(info, v)
	if info.pairs then
		return v
	end
	local enc = info.venc
	if enc == 'nilable' then
		if v == nil then
			return false
		end
	elseif enc == 'iface' then
		if v == nil then
			return NIL
		end
	end
	return v
end

local function decodeVal(info, v)
	local enc = info.venc
	if enc == 'nilable' then
		if v == false then
			return nil
		end
	elseif enc == 'iface' then
		if v == NIL then
			return nil
		end
	end
	return v
end

function rt.mgetp(m, k, MT)
	local info = MT.minfo or mapInfo(MT)
	if m == nil then
		return info.zero()
	end
	if info.pairs then
		local p = m[info.K.mapkey(k)]
		if p == nil then
			return info.zero()
		end
		return p[2]
	end
	local v = m[k == nil and NILKEY or k]
	if v == nil then
		return info.zero()
	end
	return decodeVal(info, v)
end

function rt.mget2(m, k, MT)
	local info = MT.minfo or mapInfo(MT)
	if m == nil then
		return info.zero(), false
	end
	if info.pairs then
		local p = m[info.K.mapkey(k)]
		if p == nil then
			return info.zero(), false
		end
		return p[2], true
	end
	local v = m[k == nil and NILKEY or k]
	if v == nil then
		return info.zero(), false
	end
	return decodeVal(info, v), true
end

function rt.msetp(m, k, v, MT)
	local info = MT.minfo or mapInfo(MT)
	if info.pairs then
		local ks = info.K.mapkey(k)
		local p = m[ks]
		if p == nil then
			m[LEN] = m[LEN] + 1
			m[ks] = { k, v }
		else
			p[2] = v
		end
		return
	end
	if k == nil then
		k = NILKEY
	end
	if m[k] == nil then
		m[LEN] = m[LEN] + 1
	end
	m[k] = encodeVal(info, v)
end

function rt.mdelp(m, k, MT)
	if m == nil then
		return
	end
	local info = MT.minfo or mapInfo(MT)
	local ks = k == nil and NILKEY or k
	if info.pairs then
		ks = info.K.mapkey(k)
	end
	if m[ks] ~= nil then
		m[ks] = nil
		m[LEN] = m[LEN] - 1
	end
end

function rt.maplitp(MT, kv)
	local m = rt.mkmap(math_floor(#kv / 2))
	for i = 1, #kv, 2 do
		rt.msetp(m, kv[i], kv[i + 1], MT)
	end
	return m
end

function rt.mrange(m, MT)
	local info = MT.minfo or mapInfo(MT)
	local k = nil
	if m == nil then
		return function()
			return nil
		end
	end
	return function()
		local v
		repeat
			k, v = next(m, k)
		until k ~= LEN
		if k == nil then
			return nil
		end
		if info.pairs then
			return v[1], v[2]
		end
		return k, decodeVal(info, v)
	end
end

-- mrange3 yields (control key, Go key, value) so that nil Go keys do not end the loop.
local function mrange3Next(st, k)
	local m, info = st[1], st[2]
	local v
	repeat
		k, v = next(m, k)
	until k ~= LEN
	if k == nil then
		return nil
	end
	if info.pairs then
		return k, v[1], v[2]
	end
	if k == NILKEY then
		return k, nil, decodeVal(info, v)
	end
	return k, k, decodeVal(info, v)
end

function rt.mrange3(m, MT)
	return mrange3Next, { m or E, MT.minfo or mapInfo(MT) }, nil
end
-- serialize produces a string key for struct/array map keys.
local function keyPart(T, v)
	local k = T.kind
	if k == 'string' then
		return #v .. ':' .. v
	elseif k == 'struct' or k == 'array' then
		return '{' .. rt.serialize(T, v) .. '}'
	elseif k == 'interface' then
		local ik = rt.ikey(v)
		if type(ik) == 'string' then
			return 's' .. #ik .. ':' .. ik
		end
		if type(ik) == 'number' then
			return intKey(ik)
		end
		return tostring(ik)
	elseif k == 'bool' then
		return v and 't' or 'f'
	elseif k == 'float32' or k == 'float64' then
		return sformat('%a', v)
	elseif v == nil then
		return 'n'
	end
	if type(v) == 'number' then
		return intKey(v)
	elseif type(v) == 'cdata' then
		return wideKey(v)
	end
	return tostring(v)
end

function rt.serialize(T, v)
	local parts = {}
	if T.kind == 'array' then
		for i = 1, T.len do
			parts[i] = keyPart(T.elem, v[i])
		end
	else
		for i, leaf in ipairs(leaves(T)) do
			parts[i] = keyPart(leaf[2], v[leaf[1]])
		end
	end
	return '\0' .. T.id .. '|' .. tconcat(parts, ',')
end

-- ikey converts an interface value to a Lua table key.
function rt.ikey(v)
	if v == nil then
		return NILKEY
	end
	local t = type(v)
	if t ~= 'table' then
		if t == 'string' and sbyte(v, 1) == 0 then
			return '\0s' .. v
		end
		return v
	end
	local w = rawget(v, '__t')
	if w then
		if w.kind == 'slice' or w.kind == 'map' or w.kind == 'func' then
			rt.panic(rt.runtimeError('hash of unhashable type ' .. w.str))
		end
		return '\0' .. w.id .. ':' .. keyPart(w, v.__v)
	end
	local mt = getmetatable(v)
	if mt and mt.__isval then
		return rt.serialize(mt.__struct, v)
	end
	return v
end

function rt.skey(T, v)
	return T.mapkey(v)
end

---------------------------------------------------------------------------
-- Goroutines and channels (cooperative scheduler on coroutines)

local runq, runqHead, runqTail = {}, 1, 0
local current = nil

local function enqueue(g)
	runqTail = runqTail + 1
	runq[runqTail] = g
end

local function dequeue()
	if runqHead > runqTail then
		return nil
	end
	local g = runq[runqHead]
	runq[runqHead] = nil
	runqHead = runqHead + 1
	return g
end

local function newg(f, args)
	local g = {}
	g.co = coroutine.create(function()
		f(tunpack(args, 1, args.n))
	end)
	return g
end

-- Sampling profiler (TSCLUA_PROFILE=<milliseconds>): LuaJIT's built-in profiler, which samples
-- compiled code too, counts samples per function, per source line and per VM state.
function rt.startProfile(interval)
	local profile = require('jit.profile')
	local byFunc, byLine, byState = {}, {}, {}
	local states = { N = 'compiled', I = 'interpreted', C = 'C code', G = 'garbage collector', J = 'JIT compiler' }
	profile.start('fi' .. (interval or 1), function(thread, samples, vmstate)
		local fkey = profile.dumpstack(thread, 'F', 1)
		byFunc[fkey] = (byFunc[fkey] or 0) + samples
		local lkey = profile.dumpstack(thread, 'l', 1)
		byLine[lkey] = (byLine[lkey] or 0) + samples
		local skey = states[vmstate] or vmstate
		byState[skey] = (byState[skey] or 0) + samples
	end)
	return function(out, top)
		profile.stop()
		local function dump(title, t)
			local list = {}
			local total = 0
			for k, v in pairs(t) do
				list[#list + 1] = { k, v }
				total = total + v
			end
			table.sort(list, function(a, b)
				return a[2] > b[2]
			end)
			out:write(title, string.format(' (%d samples)\n', total))
			for i = 1, math.min(top or 40, #list) do
				out:write(string.format('%6.2f%%  %s\n', list[i][2] * 100 / total, list[i][1]))
			end
		end
		dump('vm states', byState)
		dump('functions', byFunc)
		dump('lines', byLine)
	end
end

function rt.go(f, ...)
	enqueue(newg(f, table.pack(...)))
end

-- park blocks the current goroutine until rt.ready is called for it.
-- Parked goroutines are tracked so a deadlock can report where each one is blocked.
local parked = setmetatable({}, { __mode = 'k' })

function rt.park()
	if current == nil or current.main and not current.co then
		error('park outside goroutine')
	end
	parked[current] = true
	coroutine.yield()
end

function rt.ready(g)
	parked[g] = nil
	enqueue(g)
end

function rt.current()
	return current
end

function rt.gosched()
	enqueue(current)
	coroutine.yield()
end

local timers = {}

function rt.sleepUntil(t)
	timers[#timers + 1] = { t = t, g = current }
	coroutine.yield()
end

rt.clock = os.clock

local function runTimers(block)
	if #timers == 0 then
		return false
	end
	table.sort(timers, function(a, b)
		return a.t < b.t
	end)
	local now = rt.clock()
	local woke = false
	while #timers > 0 and (timers[1].t <= now or (block and not woke)) do
		local tm = table.remove(timers, 1)
		if tm.t > now and rt.sleepNative then
			rt.sleepNative(tm.t - now)
			now = rt.clock()
		end
		enqueue(tm.g)
		woke = true
	end
	return woke
end

rt.ExitError = { __name = 'ExitError' }
-- TSCLUA_CLOSE closes the Lua state on exit (slower), which LuaJIT's jit.p profiler needs to report.
rt.closeOnExit = os.getenv('TSCLUA_CLOSE') ~= nil

-- runmain runs f as the main goroutine and drives the scheduler until it returns.
function rt.runmain(f, ...)
	local main = newg(f, table.pack(...))
	main.main = true
	enqueue(main)
	while true do
		local g = dequeue()
		if g == nil then
			if not runTimers(true) then
				io.stderr:write('fatal error: all goroutines are asleep - deadlock!\n')
				for pg in pairs(parked) do
					io.stderr:write('\n', debug.traceback(pg.co, 'goroutine (blocked):'), '\n')
				end
				os.exit(2)
			end
			g = dequeue()
		end
		current = g
		local ok, err = coroutine.resume(g.co)
		current = nil
		if not ok then
			if getmetatable(err) == rt.ExitError then
				io.stdout:flush()
				if rt.onExit then
					rt.onExit()
				end
				os.exit(err.code, rt.closeOnExit)
			end
			rt.crash(err, g.co)
		end
		if coroutine.status(g.co) == 'dead' and g.main then
			return
		end
		if #timers > 0 then
			runTimers(false)
		end
	end
end

function rt.exit(code)
	error(setmetatable({ code = code }, rt.ExitError), 0)
end

function rt.panicString(v)
	if v == nil then
		return 'nil'
	end
	local ok, s = pcall(function()
		if rt.implements(typeof(v), rt.error) then
			return v:_mError()
		end
		local T = typeof(v)
		if T and T.kind == 'string' and T ~= rt.string then
			return sformat('%s(%q)', T.str, unbox(v))
		end
		if rt.fmtValue then
			return rt.fmtValue(v)
		end
		return tostring(unbox(v))
	end)
	if ok then
		return s
	end
	return tostring(v)
end

function rt.crash(err, co)
	io.stdout:flush()
	if getmetatable(err) == PanicMT then
		local v = err.value
		local msg = rt.panicString(v)
		io.stderr:write('panic: ', msg, '\n', err.tb or '', '\n')
	else
		io.stderr:write('panic: ', tostring(err), '\n')
		if co then
			io.stderr:write(debug.traceback(co), '\n')
		end
	end
	io.stderr:flush()
	os.exit(2)
end

-- Channels -----------------------------------------------------------------

local ChanMT = { __name = 'chan' }

function rt.mkchan(n)
	return setmetatable({ buf = {}, bh = 1, bt = 0, cap = n or 0, closed = false, recvq = {}, sendq = {} }, ChanMT)
end

local function qpush(q, x)
	q[#q + 1] = x
end

local function qshift(q)
	while #q > 0 do
		local w = table.remove(q, 1)
		if not (w.sel and w.sel.done) then
			return w
		end
	end
	return nil
end

local function bufLen(ch)
	return ch.bt - ch.bh + 1
end

function rt.chlen(ch)
	if ch == nil then
		return 0
	end
	return bufLen(ch)
end

function rt.chcap(ch)
	if ch == nil then
		return 0
	end
	return ch.cap
end

local function wake(w, v, ok)
	if w.sel then
		w.sel.done = true
		w.sel.idx = w.idx
		w.sel.v = v
		w.sel.ok = ok
	else
		w.v = v
		w.ok = ok
	end
	enqueue(w.g)
end

-- trySend attempts a non-blocking send; returns true on success.
local function trySend(ch, v)
	if ch.closed then
		rt.panic(rt.runtimeError('send on closed channel'))
	end
	local r = qshift(ch.recvq)
	if r then
		wake(r, v, true)
		return true
	end
	if bufLen(ch) < ch.cap then
		ch.bt = ch.bt + 1
		ch.buf[ch.bt] = v
		return true
	end
	return false
end

local function tryRecv(ch)
	if bufLen(ch) > 0 then
		local v = ch.buf[ch.bh]
		ch.buf[ch.bh] = nil
		ch.bh = ch.bh + 1
		local s = qshift(ch.sendq)
		if s then
			ch.bt = ch.bt + 1
			ch.buf[ch.bt] = s.value
			if s.sel then
				s.sel.done = true
				s.sel.idx = s.idx
			end
			enqueue(s.g)
		end
		return true, v, true
	end
	local s = qshift(ch.sendq)
	if s then
		if s.sel then
			s.sel.done = true
			s.sel.idx = s.idx
		end
		enqueue(s.g)
		return true, s.value, true
	end
	if ch.closed then
		return true, nil, false
	end
	return false
end

function rt.send(ch, v)
	if ch == nil then
		rt.park()
		return
	end
	if trySend(ch, v) then
		return
	end
	local w = { g = current, value = v }
	qpush(ch.sendq, w)
	rt.park()
	if w.closed then
		rt.panic(rt.runtimeError('send on closed channel'))
	end
end

function rt.recv2(ch, zero)
	if ch == nil then
		rt.park()
		return zero, false
	end
	local done, v, ok = tryRecv(ch)
	if done then
		if not ok then
			return zero, false
		end
		return v, ok
	end
	local w = { g = current }
	qpush(ch.recvq, w)
	rt.park()
	if not w.ok then
		return zero, false
	end
	return w.v, true
end

function rt.recv(ch, zero)
	return (rt.recv2(ch, zero))
end

function rt.close(ch)
	if ch == nil then
		rt.panic(rt.runtimeError('close of nil channel'))
	end
	if ch.closed then
		rt.panic(rt.runtimeError('close of closed channel'))
	end
	ch.closed = true
	while true do
		local r = qshift(ch.recvq)
		if not r then
			break
		end
		wake(r, nil, false)
	end
	while true do
		local s = qshift(ch.sendq)
		if not s then
			break
		end
		s.closed = true
		enqueue(s.g)
	end
end

-- select: cases are {ch, 'send', v} / {ch, 'recv'} / false (default).
-- Returns the 1-based case index and, for receives, the value and ok flag.
function rt.select(cases, hasDefault)
	local defaultIdx
	for i, c in ipairs(cases) do
		if c == false then
			defaultIdx = i
		elseif c[1] ~= nil then
			if c[2] == 'send' then
				if c[1].closed then
					rt.panic(rt.runtimeError('send on closed channel'))
				end
				if trySend(c[1], c[3]) then
					return i
				end
			else
				local done, v, ok = tryRecv(c[1])
				if done then
					return i, v, ok
				end
			end
		end
	end
	if hasDefault then
		return defaultIdx
	end
	local sel = { done = false }
	for i, c in ipairs(cases) do
		if c and c[1] ~= nil then
			if c[2] == 'send' then
				qpush(c[1].sendq, { g = current, value = c[3], sel = sel, idx = i })
			else
				qpush(c[1].recvq, { g = current, sel = sel, idx = i })
			end
		end
	end
	rt.park()
	return sel.idx, sel.v, sel.ok
end

---------------------------------------------------------------------------
-- Errors raised by the runtime itself

do
	local RE = namedType('runtime', 'runtime.Error', 'struct')
	rt.defineStruct(RE, { { 'msg', rt.string, 'msg', 0 } })
	local function errfn(e)
		return 'runtime error: ' .. e.msg
	end
	rt.methods(RE, { _mError = errfn, _mRuntimeError = function() end }, { _mError = errfn, _mRuntimeError = function() end })
	rt.runtimeErrorType = RE
	rt.runtimeErrorPtr = rt.ptrTo(RE)
	function rt.runtimeError(msg)
		msg = tostring(msg)
		return setmetatable({ msg = msg }, RE.pmt)
	end
	function rt.typeAssertionError(have, want)
		local msg
		if have == nil then
			msg = 'interface conversion: interface is nil, not ' .. typeName(want)
		elseif want.kind == 'interface' then
			msg = 'interface conversion: ' .. typeName(have) .. ' is not ' .. typeName(want) .. ': missing method'
		else
			msg = 'interface conversion: interface {} is ' .. typeName(have) .. ', not ' .. typeName(want)
		end
		local e = setmetatable({ msg = msg }, RE.pmt)
		return e
	end
end

---------------------------------------------------------------------------
-- print/println builtins (write to stderr like Go)

local function printArg(v)
	local t = type(v)
	if t == 'table' and rawget(v, '__t') then
		v = v.__v
		t = type(v)
	end
	if t == 'number' then
		if v ~= math_floor(v) then
			return sformat('%+e', v)
		end
		return sformat('%d', v)
	elseif t == 'cdata' then
		return (tostring(v):gsub('U?LL$', ''))
	elseif t == 'nil' then
		return 'nil'
	elseif t == 'table' then
		return sformat('0x%x', 0)
	end
	return tostring(v)
end

function rt.print(...)
	local parts = {}
	for i = 1, select('#', ...) do
		parts[i] = printArg((select(i, ...)))
	end
	io.stderr:write(tconcat(parts))
end

function rt.println(...)
	local parts = {}
	for i = 1, select('#', ...) do
		parts[i] = printArg((select(i, ...)))
	end
	io.stderr:write(tconcat(parts, ' '), '\n')
end

---------------------------------------------------------------------------
-- Embedded files (//go:embed)

rt.embedRoot = nil

function rt.readEmbed(pkgmod, name)
	if rt.embedReader then
		return rt.embedReader(pkgmod, name)
	end
	local root = rt.embedRoot or 'build/embed'
	local f = io.open(root .. '/' .. pkgmod .. '/' .. name, 'rb')
	if not f then
		return nil
	end
	local data = f:read('*a')
	f:close()
	return data
end

-- embed resolves a //go:embed variable; files live under <embed root>/<module name>/.
function rt.embed(mod, kind, patterns)
	if rt.embedHandler then
		return rt.embedHandler(mod, kind, patterns)
	end
	if kind == 'string' or kind == 'bytes' then
		local data = rt.readEmbed(mod, patterns[1])
		if data == nil then
			error('missing embedded file ' .. mod .. '/' .. patterns[1])
		end
		if kind == 'bytes' then
			return rt.strbytes(data)
		end
		return data
	end
	error('embed.FS is not supported for ' .. mod)
end

return rt
